join ensino.turma t on t


select
	mc.id_matricula_componente, mc.id_situacao_matricula, mc.id_matricula_estudante_serie --string_agg(id_matricula_componente :: varchar, ', ' )
from
	ensino.matricula_componente mc
left outer join ensino.turma t on mc.id_turma = t.id_turma
left outer join basico.turma_serie ts on
	t.id_turma_serie = ts.id_turma_serie
where
	mc.id_discente = 986133
	and t.ano = 2023
	and t.id_turma_serie = 53618308;
--and mc.id_matricula_estudante_serie = 1345558;
--and id_matricula_componente in (17436916, 17436917, 17436922, 17436925, 17436924, 17436926, 17436915, 17436918, 17436919, 17436920, 17436921, 17436923);
	and mc.id_matricula_estudante_serie is null;
	and t.id_situacao_turma <> 4
	and (mc.id_situacao_matricula in (5 , 6 , 2 , 8))
	and (t.tipo not in (4 , 18))
	and (mc.id_matricula_estudante_serie = 1343930 or mc.id_matricula_estudante_serie is null);
